def split_permutation(n, permutation):
    # This function splits the permutation into at most f(n) monotonic subsequences
    # where f(n) is the minimum integer k such that every permutation of length n can be partitioned into at most k monotonic subsequences.
    # The function returns the number of subsequences and the subsequences themselves.

    # The value of f(n) is known to be 2 for all n, as we can always split the permutation into two monotonic subsequences.
    subsequences = []

    # Split the permutation into two monotonic subsequences
    increasing = []
    decreasing = []

    for num in permutation:
        if not increasing or num > increasing[-1]:
            increasing.append(num)
        elif not decreasing or num < decreasing[-1]:
            decreasing.append(num)
        else:
            # If neither increasing nor decreasing can accommodate the number, we need to start a new subsequence
            if increasing[-1] < decreasing[-1]:
                subsequences.append(increasing)
                increasing = [num]
            else:
                subsequences.append(decreasing)
                decreasing = [num]

    # Append the remaining subsequences
    if increasing:
        subsequences.append(increasing)
    if decreasing:
        subsequences.append(decreasing)

    return subsequences

